with d as (select value r from jsonb_array_elements($q$[{"steps":[{"text":"Heat the sesame oil in a large wok or wide frying pan over medium-high heat."},{"text":"Add the zucchini and salt. Stir-fry, tossing gently and frequently, until the zucchini is tender but still holds its shape and the edges are lightly caramelised, about 6–8 minutes. The zucchini will release a little moisture; let it cook off."},{"text":"Remove from the heat and allow to cool for a minute. Add the perilla leaves and toss gently to combine."},{"text":"Transfer to a serving bowl, scatter with the sesame seeds and black pepper, and serve at room temperature or slightly warm."}],"id":"6cf870e1-c10d-4f1e-9938-6d33defc9dae"},{"steps":[{"text":"Dice the tomatoes into small, even pieces, about the size of a pea. If they release a lot of juice, drain them slightly."},{"text":"Dice the white onion into small pieces the same size as the tomato."},{"text":"Chop the fresh coriander roughly, then go over it once more with the knife so it's fine."},{"text":"Combine the tomato, onion and coriander in a bowl."},{"text":"Squeeze the lime juice over, add a pinch of salt, and stir gently until the tomato is glossy and lightly coated in juice. Taste and adjust salt and lime."},{"text":"Serve right away, or cover and keep in the fridge for up to an hour."}],"id":"1b7a0a26-a44c-4fbd-a1fe-5315867743f6"},{"notes":["Make the broth ahead and reheat gently; it keeps for 3 days in the fridge. Cook the noodles fresh just before serving.","No fresh crab? Use a good tinned crab in brine (drain well), or substitute more crab paste with a little extra stock to thin it.","The fried shallots are worth finding at any Vietnamese or Asian grocer, they're the difference between good and the stall version.","Cook chicken until it reaches 75°C in the thickest part and the juices run clear.","Food safety: Cook fish until it is opaque and flakes easily (63°C in the thickest part), and prawns until pink and opaque all the way through."],"id":"d26e8327-44fd-4cce-9850-5fc4adbf165e"},{"notes":["Marinate the chicken overnight for best flavour, it's worth the patience.","Use bone-in, skin-on chicken; it stays juicier and develops that crackling skin Yogyakarta style.","Serve at room temperature with steamed rice and sambal if you like heat.","Food safety: Cook chicken (and other poultry) until the thickest part reaches 75°C and the juices run clear, with no pink meat near the bone."],"id":"7d22dab0-a9fe-48d2-a5ca-39bd13cf6f2b"},{"notes":["Snapper is the go-to, firm, sweet, cooks quickly. Sub any fresh white fish fillet.","Make it vegetarian: swap the fish for 250 g firm tofu, cut into thick slices, pan-seared until golden.","Food safety: Cook fish until it turns opaque and flakes easily, about 63°C in the thickest part."],"id":"01b02dd2-4251-4de7-bca0-1e1bb49a8e1b"},{"notes":["Cook chicken until it reaches 75°C in the thickest part and the juices run clear."],"id":"ee03b726-032d-4ecd-9ff5-57319a904d34"},{"notes":["Fresh molokhia is best and usually the cheapest; dried molokhia works too, use half the weight and crush it into a powder before adding. Frozen molokhia is also fine.","If you can't find molokhia, spinach is the closest substitute, though it's leafier and less slimy. Don't overcook spinach or it falls apart.","The stew thickens as it cools; add a splash more stock when reheating if needed."],"steps":[{"text":"Bring the vegetable stock to a boil in a large pot, until it bubbles steadily."},{"text":"Add the chopped molokhia leaves and stir to combine. Simmer for 5 minutes until the leaves start to break down."},{"text":"While the molokhia simmers, heat a tablespoon of oil in a small pan over medium heat. Add the chopped garlic and fry gently, stirring often, until golden and fragrant, about 3 minutes."},{"text":"Crush the fried garlic with the salt using the back of a spoon or a mortar and pestle until it forms a paste."},{"text":"Stir the garlic paste and ground coriander into the molokhia. Simmer for a further 3 to 5 minutes until the stew is thick and cohesive."},{"text":"Serve the molokhia over a bed of steamed rice, with lemon wedges on the side for squeezing."}],"id":"b491b07d-d5fe-489b-a794-302671fec1cf"},{"steps":[{"text":"Rinse the yellow split peas under cold water, then tip into a large pot with the water and quartered brown onion. Bring to a boil, then reduce the heat and simmer gently, uncovered, for about 50 minutes, stirring often, until the peas have broken down completely into a thick purée."},{"text":"When the peas are very soft and falling apart, remove from the heat and discard the onion pieces. Season generously with salt."},{"text":"Whisk in the olive oil, a little at a time, beating to incorporate air and make the purée smooth and pale. This will take 3–4 minutes of steady whisking."},{"text":"Stir in the lemon juice, then taste and adjust the seasoning, you want salt, brightness and richness in balance."},{"text":"Divide among four bowls and top each with a handful of raw red onion slices and a crack of black pepper. Serve warm or at room temperature."}],"id":"8c512d47-9cb7-4093-8f12-2f2f2ad73bea"},{"notes":["If you can't find ready-made tarhana paste, you can order it online. Turkish delis often stock it.","Tarhana keeps for months in an airtight jar, so it's worth having on hand.","A dollop of yoghurt stirred in at the end is traditional, use about 1 tbsp per bowl.","Cook chicken until it reaches 75°C in the thickest part and the juices run clear."],"id":"75d6ab6d-b413-4e95-8003-9da5e2bc2126"},{"steps":[{"text":"If using a whole coconut, pierce the eyes and drain the liquid. Crack open the shell and peel away the brown skin with a vegetable peeler. Grate the white flesh on a fine grater or microplane until you have about 400 g of fine, fluffy coconut."},{"text":"Put the grated coconut into a bowl and add the lime juice, chopped chillies, pounded dried fish, and red onion."},{"text":"Mix gently but thoroughly until every grain of coconut is coated and the flavours are even."},{"text":"Taste and adjust the seasoning with salt. The sambol should be bright, sharp, and hot, not timid."},{"text":"Serve immediately alongside hot rice and curry."}],"id":"b8128269-ec85-43bf-9dbc-7edc93d7253b"},{"notes":["Make the filling and dough ahead: the filling keeps for 2 days in the fridge, and the dough keeps for up to 4 hours. You can freeze uncooked pierogi on a tray, then boil them straight from frozen (add 1 extra minute to the boiling time).","A potato ricer or food mill makes a smoother filling if you don't like lumps, though a rustic texture is traditional too.","Food safety: Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"steps":[{"text":"Make the dough: mix flour and salt in a bowl. In another bowl, whisk the egg, then stir in the sour cream. Pour the wet mixture into the flour and mix until you have a soft, slightly sticky dough. Knead for 5 minutes until smooth and elastic. Cover and rest for 30 minutes."},{"text":"Meanwhile, make the filling: boil the potato pieces in salted water until very tender, about 12 minutes. Drain well and mash roughly, you want some small lumps. Fry the chopped onion in 2 tbsp butter over medium heat until soft and golden, about 5 minutes. Stir the onion and butter into the potato, then fold in the cheese. Season to taste with salt and pepper. Let cool."},{"text":"Make the caramelized onions for serving: slice the 2 onions thinly. Melt 3 tbsp butter in a wide pan over medium heat and cook the onions, stirring often, until they're golden and soft, about 15 minutes. Set aside."},{"text":"Roll the pierogi: flour your work surface lightly. Roll the dough out to about 2 mm thick. Using a 7 cm round cutter or a glass, cut out circles. Place a heaped teaspoon of filling on each circle, fold in half, then press the edges to seal, fold the corner of the half-moon up and over itself to make a small curved seal (this is the traditional shape). Oil your hands if the dough sticks."},{"text":"Bring a large pot of salted water to a boil. Working in batches, drop the pierogi in. They'll sink at first, then float to the surface when they're nearly done, about 2 minutes. Boil for another 30 seconds after they float, then lift out with a slotted spoon."},{"text":"Serve the pierogi warm with the caramelized onions spooned over the top and a dollop of sour cream. Scatter with fresh dill if you like."}],"id":"c92a67ba-17c0-4c71-a6dc-63508785eb28"},{"notes":["The curry can be made a day ahead and reheated gently. The sambals are best made an hour or two before serving so the flavours meld.","Use leftover roast chicken or vegetables instead of making the curry, a generous spoonful stirred through the rice works just as well.","The rice can also be cooked in a rice cooker: fry the onion, garlic and ginger in a pot, add turmeric and rice to coat, then transfer to the rice cooker with the stock and bay leaves.","Cook mince and sausages until they reach 75°C in the centre, with no pink left.","Food safety: Cook mince, sausages, meatballs and liver right through to 75°C, with no pink in the centre."],"id":"81de07e0-e8d4-40c9-addf-f77c7f6e58c9"},{"notes":["Make this a day ahead: the pralines soften beautifully overnight and the flavours deepen.","Pink pralines are a Lyon specialty and worth hunting down in good delis or online. They're crunchy, delicately flavoured hazelnut pralines and not like anything else.","If your oven runs hot, tent the tart loosely with foil if it's browning too quickly.","Food safety: The eggs are cooked until just set. For pregnant women, young children, older people or anyone with a weakened immune system, cook them until firm all the way through."],"steps":[{"text":"Make the pastry: rub the cold butter into the flour with your fingertips until it looks like breadcrumbs, then stir in the caster sugar and salt. Beat the egg yolk with the cold water and mix into the flour until just combined. Form a disc, wrap in cling film and refrigerate for at least 30 minutes."},{"text":"Preheat the oven to 200°C. Roll out the pastry between two sheets of baking paper to about 3 mm thick. Press into a 24 cm tart tin, trim the edges and prick the base. Blind bake with baking paper and beans for 12 minutes, then remove the paper and beans and bake for another 5 minutes until just set. Set aside to cool slightly."},{"text":"Roughly crush about three-quarters of the pink pralines with the back of a spoon, you want some texture, not a smooth paste. Stir the softened butter through the crushed pralines."},{"text":"Whisk the cream, milk, egg yolks and vanilla together until smooth. Fold in the praline mixture, then pour into the cooled pastry shell. Scatter the remaining whole pralines over the top."},{"text":"Bake at 180°C for about 10 minutes, until the filling is just set but still trembling slightly in the centre. The tart will continue to set as it cools. Chill for at least 4 hours, or overnight, before serving."}],"id":"b74d0eae-b854-4fff-b755-71ba99553eb6"},{"notes":["The whole point is freshness and gentleness. Don't rush the poaching, low heat keeps the fish tender. If your fillets are very thick, give them an extra minute.","Brown butter can be made ahead and kept warm; reheat gently before serving.","Food safety: Cook fish until it turns opaque and flakes easily, about 63°C in the thickest part."],"steps":[{"text":"Pour the stock or water into a wide, shallow pan and add the bay leaf. Bring to a gentle simmer over medium heat, until the surface is barely trembling with tiny bubbles and not boiling."},{"text":"Pat the fish fillets dry with paper towel and season lightly with salt on both sides."},{"text":"Slide the fish into the simmering stock. The liquid should barely cover them. Poach gently, the surface should barely tremble, for about 8 minutes, until the fish is cooked through and flakes easily when tested with a fork."},{"text":"Carefully lift the fish onto warm plates using a slotted spatula, leaving the poaching liquid behind."},{"text":"Melt the butter in a small pan over medium heat, swirling occasionally, until it turns a light golden brown and smells nutty, about 3 minutes. Watch it carefully so it doesn't burn."},{"text":"Drizzle the brown butter, which should smell nutty and be golden brown, over each fillet, which should be opaque and flake easily. Scatter the chives over the top, and finish with a grind of black pepper. Serve at once."}],"id":"7d15940a-33a0-4b5e-8a19-5c320c151852"},{"notes":["The dough keeps well: store finished pancakes in an airtight container for 2 days, then reheat briefly in a dry frying pan. You can also freeze uncooked rested discs for up to a month, then cook straight from frozen (add 2 minutes to the cooking time).","Hydration is key here, 75% feels sticky at first, but it's what gives you those delicate, shattering layers. Don't add extra flour."],"steps":[{"text":"Mix the boiling water into the flour and salt with a wooden spoon or chopsticks until shaggy. Let cool for 5 minutes, then knead by hand until smooth and soft, about 8 minutes. The dough will be slightly sticky, this is right. Cover with a damp cloth and rest for 20 minutes."},{"text":"Divide the dough into 4 equal pieces. Roll each piece into a ball, brush all over with a little oil, and rest for 10 minutes covered."},{"text":"On an oiled work surface, roll one ball into a thin rectangle about 30 cm × 20 cm. Brush generously with oil, scatter a quarter of the chopped spring onion evenly over the surface, then tightly roll up from one long edge into a log. Coil the log into a spiral, tucking the end underneath. Press gently to flatten slightly into a disc about 1 cm thick. Repeat with the remaining dough balls, spring onion and oil. Let rest for 5 minutes."},{"text":"Roll each disc into a round about 20 cm across, being gentle so the layers stay distinct. If the dough springs back, let it rest for a minute and try again."},{"text":"Heat 1½ tbsp oil in a large non-stick frying pan over medium heat. Once shimmering, place one pancake in and cook for 2–3 minutes until the underside is golden and crispy. Flip and cook the other side for 1–2 minutes until speckled and cooked through."},{"text":"Transfer to a plate and immediately sprinkle with a pinch of coarse sea salt. Repeat with the remaining pancakes, adding a little more oil to the pan as needed. Serve warm, torn into pieces."}],"id":"dca90649-8e17-452d-8c83-516cc2a998f6"}]$q$::jsonb)), up as (update public.published_recipes p set recipe = p.recipe || (d.r - 'id' - 'notes') || case when d.r ? 'notes' then jsonb_build_object('notes', coalesce((select jsonb_agg(n) from jsonb_array_elements(d.r->'notes') n where btrim(n#>>'{}') <> 'Food safety:'),'[]'::jsonb)) else '{}'::jsonb end, diets = case when d.r ? 'diets' then array(select jsonb_array_elements_text(d.r->'diets')) else p.diets end from d where p.id=(d.r->>'id')::uuid returning p.id) select (select count(*) from d) expected, (select count(*) from up) updated;